import{_ as t,o as a,c as r,a3 as o}from"./chunks/framework.B5WAEDB7.js";const p=JSON.parse('{"title":"Version History","description":"Trace changes to an entry and restore earlier values.","frontmatter":{"title":"Version History","description":"Trace changes to an entry and restore earlier values."},"headers":[],"relativePath":"en/grids/versionsverlauf.md","filePath":"en/grids/versionsverlauf.md","lastUpdated":1787319236000}'),n={name:"en/grids/versionsverlauf.md"};function s(i,e,h,l,d,g){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="version-history" tabindex="-1">Version History <a class="header-anchor" href="#version-history" aria-label="Permalink to &quot;Version History&quot;">​</a></h1><p>The version history shows <strong>who changed what, when</strong> on an entry — and lets you bring back earlier values.</p><p>In the interface, this area is called <strong>Changes</strong>.</p><h2 id="opening-the-history" tabindex="-1">Opening the history <a class="header-anchor" href="#opening-the-history" aria-label="Permalink to &quot;Opening the history&quot;">​</a></h2><p>Open an entry and switch to <strong>Changes</strong>.</p><p>For each change, you see:</p><table tabindex="0"><thead><tr><th>Item</th><th>Example</th></tr></thead><tbody><tr><td>Who</td><td><em>{Name} edited this entry</em></td></tr><tr><td>When</td><td>Timestamp</td></tr><tr><td>What</td><td>Field name with <strong>Old</strong> and <strong>New</strong></td></tr></tbody></table><p>Creation appears as <em>{Name} created this entry</em>.</p><p>Clicking the timestamp toggles between relative and absolute display: <em>Click to switch between relative and absolute time format.</em></p><p><strong>Load more changes</strong> loads older entries.</p><h2 id="who-triggered-a-change" tabindex="-1">Who triggered a change <a class="header-anchor" href="#who-triggered-a-change" aria-label="Permalink to &quot;Who triggered a change&quot;">​</a></h2><p>Not every change comes from a person:</p><table tabindex="0"><thead><tr><th>Display</th><th>Meaning</th></tr></thead><tbody><tr><td>A name</td><td>A person made the edit</td></tr><tr><td><strong>Form</strong></td><td>The change came in via a <a href="/en/formulare/formular-erstellen">form</a></td></tr><tr><td><strong>System or Flow</strong></td><td>A <a href="/en/flows/was-ist-ein-flow">flow</a> or an automatic process</td></tr><tr><td><strong>Unknown user</strong></td><td>The person can no longer be resolved</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">The fastest way to the cause</p><p>If a value seemed to change &quot;by itself,&quot; the history usually clears it up right away: if it says <em>System or Flow</em>, check this Grid&#39;s flows — one of them is probably reacting to a change and writing back.</p></div><p>Empty values appear as <strong>(empty)</strong>, checkmarks as <strong>Yes</strong> and <strong>No</strong>. If a field has since been deleted, it shows <em>Unknown field</em>.</p><h2 id="restoring-a-value" tabindex="-1">Restoring a value <a class="header-anchor" href="#restoring-a-value" aria-label="Permalink to &quot;Restoring a value&quot;">​</a></h2><p>Use <strong>Reset to this value</strong> to bring back an earlier value.</p><div class="warning custom-block"><p class="custom-block-title">Resetting creates a new change</p><blockquote><p><em>This does not delete the entry from the history. It creates a new change with the old value.</em></p></blockquote><p>So the history isn&#39;t rewound. Instead, a further step is added that sets the old value again.</p><p>That&#39;s by design — the history stays complete. But: this new change is a change like any other and can start a <a href="/en/flows/trigger">flow</a> with the <em>Entry was changed</em> trigger.</p></div><p>The confirmation dialog is called <strong>Create new change with old value</strong>.</p><h2 id="retention-period" tabindex="-1">Retention period <a class="header-anchor" href="#retention-period" aria-label="Permalink to &quot;Retention period&quot;">​</a></h2><p>How far back the history goes depends on your plan. The app shows it, for example:</p><blockquote><p><em>You have 1 week of revision history.</em></p></blockquote><p>Depending on the plan, this shows <strong>1 day</strong>, <strong>1 week</strong>, or <strong>4 weeks</strong>.</p><div class="warning custom-block"><p class="custom-block-title">Older changes are gone for good</p><p>Once the retention period has passed, earlier values can no longer be viewed or restored.</p><p>For long-term traceability — for legal reasons, say — the version history isn&#39;t enough. In that case, deliberately log changes as data: an additional &quot;Log&quot; Grid that a <a href="/en/flows/aktionen">flow</a> writes to on every relevant change.</p></div><p>If nothing is available, <em>No revision history available</em> appears; while loading, <em>Loading revision history…</em>.</p><h2 id="what-the-history-doesn-t-cover" tabindex="-1">What the history doesn&#39;t cover <a class="header-anchor" href="#what-the-history-doesn-t-cover" aria-label="Permalink to &quot;What the history doesn&#39;t cover&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">Deleted entries can&#39;t be restored</p><p>The version history logs changes to the <strong>field values</strong> of an existing entry. A deleted entry is gone — the history doesn&#39;t bring it back.</p><p>So take a <a href="/en/grids/csv-export">CSV export</a> before larger deletion actions. → <a href="/en/grids/eintraege-loeschen">Deleting entries</a></p></div><p>Also not tracked: changes to structure — fields created, renamed, or deleted, changed views, forms, and flows.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/grids/eintraege">Creating and editing entries</a></li><li><a href="/en/grids/eintraege-loeschen">Deleting entries</a></li><li><a href="/en/grids/csv-export">CSV Export</a> — backing up data</li></ul>',30)])])}const m=t(n,[["render",s]]);export{p as __pageData,m as default};
